def make_metavar(self, ctx: Context) -> str:
    if self.metavar is not None:
        return self.metavar
    var = self.type.get_metavar(param=self, ctx=ctx)
    if var:
        # The type rendered its own metavar, such as ``[foo|bar]`` for a
        # Choice. It already uses brackets to show whether the value is
        # required, so don't wrap it again.
        if self.deprecated:
            var += "!"
    else:
        var = self.name.upper()
        if self.deprecated:
            var += "!"
        if not self.required:
            var = f"[{var}]"
    if self.nargs != 1:
        var += "..."
    return var

