def make_metavar(self, ctx: Context) -> str:
    if self.metavar is not None:
        return self.metavar
    var = self.type.get_metavar(param=self, ctx=ctx)
    if not var:
        var = self.name.upper()
    if self.deprecated:
        var += "!"
    # A type may already render brackets around its own metavar, such as
    # Choice or DateTime. Don't add a second pair for optional arguments.
    if not self.required and not var.startswith("["):
        var = f"[{var}]"
    if self.nargs != 1:
        var += "..."
    return var
